-- FEAT-009 (My Grades), Phase 4: reminders 5 and 2 days before a dated
-- assessment, generated by the existing reminder rules. Additive only: a new
-- reminder source, a nullable link from a reminder to its assessment, and two
-- switches that default to on. Written to be safe to re-run.

-- Not used in this migration, so adding it inside the migration's transaction is fine.
ALTER TYPE "ReminderSource" ADD VALUE IF NOT EXISTS 'ASSESSMENT';

ALTER TABLE "reminders" ADD COLUMN IF NOT EXISTS "assessment_id" UUID;

-- The global switch, on the student's reminder rules.
ALTER TABLE "reminder_settings" ADD COLUMN IF NOT EXISTS "assessment_enabled" BOOLEAN NOT NULL DEFAULT true;

-- The per-assessment switch.
ALTER TABLE "assessments" ADD COLUMN IF NOT EXISTS "remind" BOOLEAN NOT NULL DEFAULT true;

CREATE INDEX IF NOT EXISTS "reminders_assessment_id_idx" ON "reminders"("assessment_id");

DO $$ BEGIN
  ALTER TABLE "reminders" ADD CONSTRAINT "reminders_assessment_id_fkey"
    FOREIGN KEY ("assessment_id") REFERENCES "assessments"("id") ON DELETE CASCADE ON UPDATE CASCADE;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;
